def evaluate_expression(expr: str) -> str:
    try:
        # Define allowed operators
        allowed_operators = {'+', '-', '*', '/'}

        # Split the expression into tokens (numbers and operators)
        tokens = expr.replace(' ', '').split()

        # Validate tokens
        if len(tokens) != 3 or tokens[1] not in allowed_operators:
            return ""

        num1, op, num2 = float(tokens[0]), tokens[1], float(tokens[2])

        # Perform the operation
        if op == '+':
            result = num1 + num2
        elif op == '-':
            result = num1 - num2
        elif op == '*':
            result = num1 * num2
        elif op == '/':
            if num2 != 0:
                result = num1 / num2
            else:
                return ""

        return str(result)

    except Exception as e:
        return ""
